INSERT INTO `chapters` VALUES (1,1,'Mecanique du Point et du Solide','mecanique-point-solide','Cinematique, dynamique newtonienne, energetique et oscillateurs mecaniques.',NULL,'l1',1,1,'2026-08-13 19:23:45'),(2,1,'Thermodynamique Statistique & Macroscopique','thermodynamique','Principes de la thermodynamique, machines thermiques et entropie.',NULL,'l2',2,2,'2026-08-13 19:23:45'),(3,1,'Electromagnetisme dans le vide & les milieux','electromagnetisme','Equations de Maxwell, ondes electromagnetiques et induction.',NULL,'l2',3,3,'2026-08-13 19:23:45'),(4,2,'Cinetique Chimique & Catalyse','cinetique-chimique','Vitesses de reaction, lois d ordre et cinetique enzymatique.',NULL,'l1',1,1,'2026-08-13 19:23:45'),(5,2,'Chimie Organique : Mecanismes & Stereochimie','chimie-organique','Substitution nucleophile, elimination, addition et stereochimie.',NULL,'l2',2,2,'2026-08-13 19:23:45'),(6,1,'Ondes sur une corde vibrante','tome-1-ondes-mecaniques-ch1-ondes-sur-une-corde-vibrante','Équation d\'Alembert, ondes progressives, réflexions aux limites, modes propres et énergie vibratoire.','Tome 1 : Ondes Mécaniques','l2',1,1,'2026-08-13 20:53:55'),(7,1,'Ondes acoustiques dans un fluide','tome-1-ondes-mecaniques-ch2-ondes-acoustiques-dans-un-fluide','Propagation acoustique, équations d\'état des fluides, impédance acoustique, énergie et effet Doppler.','Tome 1 : Ondes Mécaniques','l2',2,2,'2026-08-13 20:53:55'),(8,1,'Autres types d\'ondes 1D (Barres, Câbles, Réseaux)','tome-1-ondes-mecaniques-ch3-autres-types-d-ondes-1d','Ondes longitudinales dans les barres, milieux dispersifs, vitesse de phase et vitesse de groupe.','Tome 1 : Ondes Mécaniques','l2',3,3,'2026-08-13 20:53:55'),(9,1,'Ondes de gravitation dans un liquide (Houle, Vagues)','tome-1-ondes-mecaniques-ch4-ondes-de-gravitation-liquide','Théorie de la houle, équation d\'onde en eau profonde et peu profonde, dispersion et solitons.','Tome 1 : Ondes Mécaniques','l2',4,4,'2026-08-13 20:53:55'),(10,1,'Diffusion thermique et de particules','tome-1-ondes-mecaniques-ch5-diffusion-thermique-et-particules','Loi de Fick, équation de la chaleur, régimes stationnaires et sinusoïdaux, marche au hasard.','Tome 1 : Ondes Mécaniques','l2',5,5,'2026-08-13 20:53:55'),(11,1,'Ondes Électromagnétiques dans le vide (OPPM)','tome-2-ondes-em-vide-milieux-ch1-oem-dans-le-vide','Équations de Maxwell dans le vide, onde plane progressive harmonique, polarisation, vecteur de Poynting et pression de radiation.','Tome 2 : Ondes Électromagnétiques dans le Vide et les Milieux','l2',6,6,'2026-08-13 20:53:55'),(12,1,'Lignes de transmission','tome-2-ondes-em-vide-milieux-ch2-lignes-de-transmission','Équations des télégraphistes, impédance caractéristique, réflexions et régime sinusoïdal sur ligne.','Tome 2 : Ondes Électromagnétiques dans le Vide et les Milieux','l2',7,7,'2026-08-13 20:53:56'),(13,1,'Conducteurs métalliques et guides d\'ondes','tome-2-ondes-em-vide-milieux-ch3-conducteurs-metalliques','Effet de peau, réflexion sur un conducteur parfait ou réel, propagation guidée et cavités résonantes.','Tome 2 : Ondes Électromagnétiques dans le Vide et les Milieux','l2',8,8,'2026-08-13 20:53:56'),(14,1,'Ondes électromagnétiques dans un plasma','tome-2-ondes-em-vide-milieux-ch4-ondes-dans-un-plasma','Modèle d\'Drude-Lorentz, fréquence plasma, propagation et réflexion ionosphérique.','Tome 2 : Ondes Électromagnétiques dans le Vide et les Milieux','l2',9,9,'2026-08-13 20:53:56'),(15,1,'Rayonnement dipolaire et diffusion','tome-2-ondes-em-vide-milieux-ch5-rayonnement-dipolaire-diffusion','Potentiels retardés, dipôle oscillant de Hertz, puissance rayonnée et diffusion Rayleigh / Thomson.','Tome 2 : Ondes Électromagnétiques dans le Vide et les Milieux','l2',10,10,'2026-08-13 20:53:56'),(16,1,'Introduction aux milieux diélectriques','tome-3-ondes-em-dielectriques-ch1-introduction-dielectriques','Polarisation de la matière, vecteur déplacement électrique D, polarisabilité moléculaire et condensateurs.','Tome 3 : Ondes Électromagnét