INSERT INTO `courses` VALUES (1,1,'Cinematique du point materiel','cinematique-point','Vecteurs position, vitesse, acceleration en coordonnees cartesiennes et cylindriques.','Contenu detaille du cours de cinematique...','/assets/downloads/fiches-mecanique.pdf','l1',1,'2026-08-13 19:23:45'),(2,1,'Oscillateurs mecaniques amortis et forces','oscillateurs-mecaniques','Etude du regime harmonique, facteur de qualite et resonance.','Contenu detaille des oscillateurs...','/assets/downloads/fiches-mecanique.pdf','l1',2,'2026-08-13 19:23:45'),(3,2,'Les deux premiers principes de la thermodynamique','principes-thermodynamique','Bilan d energie, enthalpie, entropie et machines de Carnot.','Contenu detaille de thermodynamique...','/assets/downloads/formulaire-thermo.pdf','l2',3,'2026-08-13 19:23:45'),(6,6,'Chapitre 1 - Ondes sur une corde vibrante','cours-tome-1-ondes-mecaniques-ch1-ondes-sur-une-corde-vibrante','Équation d\'Alembert, ondes progressives, réflexions aux limites, modes propres et énergie vibratoire.',NULL,'/assets/downloads/garing_decoupe/Tome_1_Ondes_Mecaniques/Chapitres/Chapitre_1_Ondes_sur_une_corde_vibrante.pdf','l2',1,'2026-08-13 20:53:55'),(7,7,'Chapitre 1 - Ondes acoustiques dans un fluide','cours-tome-1-ondes-mecaniques-ch2-ondes-acoustiques-dans-un-fluide','Propagation acoustique, équations d\'état des fluides, impédance acoustique, énergie et effet Doppler.',NULL,'/assets/downloads/garing_decoupe/Tome_1_Ondes_Mecaniques/Chapitres/Chapitre_2_Ondes_acoustiques_dans_un_fluide.pdf','l2',1,'2026-08-13 20:53:55'),(8,8,'Chapitre 1 - Autres types d\'ondes 1D (Barres, Câbles, Réseaux)','cours-tome-1-ondes-mecaniques-ch3-autres-types-d-ondes-1d','Ondes longitudinales dans les barres, milieux dispersifs, vitesse de phase et vitesse de groupe.',NULL,'/assets/downloads/garing_decoupe/Tome_1_Ondes_Mecaniques/Chapitres/Chapitre_3_Autres_types_d_ondes_1D.pdf','l2',1,'2026-08-13 20:53:55'),(9,9,'Chapitre 1 - Ondes de gravitation dans un liquide (Houle, Vagues)','cours-tome-1-ondes-mecaniques-ch4-ondes-de-gravitation-liquide','Théorie de la houle, équation d\'onde en eau profonde et peu profonde, dispersion et solitons.',NULL,'/assets/downloads/garing_decoupe/Tome_1_Ondes_Mecaniques/Chapitres/Chapitre_4_Ondes_de_gravitation_liquide.pdf','l2',1,'2026-08-13 20:53:55'),(10,10,'Chapitre 1 - Diffusion thermique et de particules','cours-tome-1-ondes-mecaniques-ch5-diffusion-thermique-et-particules','Loi de Fick, équation de la chaleur, régimes stationnaires et sinusoïdaux, marche au hasard.',NULL,'/assets/downloads/garing_decoupe/Tome_1_Ondes_Mecaniques/Chapitres/Chapitre_5_Diffusion_Thermique_et_Particules.pdf','l2',1,'2026-08-13 20:53:55'),(11,11,'Chapitre 1 - Ondes Électromagnétiques dans le vide (OPPM)','cours-tome-2-ondes-em-vide-milieux-ch1-oem-dans-le-vide','Équations de Maxwell dans le vide, onde plane progressive harmonique, polarisation, vecteur de Poynting et pression de radiation.',NULL,'/assets/downloads/garing_decoupe/Tome_2_Ondes_EM_Vide_et_Milieux/Chapitres/Chapitre_1_OEM_dans_le_vide.pdf','l2',1,'2026-08-13 20:53:55'),(12,12,'Chapitre 1 - Lignes de transmission','cours-tome-2-ondes-em-vide-milieux-ch2-lignes-de-transmission','Équations des télégraphistes, impédance caractéristique, réflexions et régime sinusoïdal sur ligne.',NULL,'/assets/downloads/garing_decoupe/Tome_2_Ondes_EM_Vide_et_Milieux/Chapitres/Chapitre_2_Lignes_de_transmission.pdf','l2',1,'2026-08-13 20:53:56'),(13,13,'Chapitre 1 - Conducteurs métalliques et guides d\'ondes','cours-tome-2-ondes-em-vide-milieux-ch3-conducteurs-metalliques','Effet de peau, réflexion sur un conducteur parfait ou réel, propagation guidée et cavités résonantes.',NULL,'/assets/downloads/garing_decoupe/Tome_2_Ondes_EM_Vide_et_Milieux/Chapitres/Chapitre_3_Conducteurs_metalliques.pdf','l2',1,'2026-08-13 20:53:56'),(14,14,'Chapitre 1 - Ondes électromagnétiques dans un plasma','cours-tome-2-ondes-em-vide-milieux-ch4-ondes-dans-un-plasma','Modèle d\'Drude-Lorentz, fréquence plasma, propagation et réflexion ionosphérique.',NULL,'/assets/downloads/garing_decoupe/Tome_2_Ondes_EM_Vide_et_Milieux/Chapitres/Chapitre_4_Ondes_dans_un_plasma.pdf','l2',1,'2026-08-13 20:53:56'),(15,15,'Chapitre 1 - Rayonnement dipolaire et diffusion','cours-tome-2-ondes-em-vide-milieux-ch5-rayonnement-dipolaire-diffusion','Potentiels retardés, dipôle oscillant de Hertz, puissance rayonnée et diffusion Rayleigh / Thomson.',NULL,'/assets/downloads/garing_decoupe/Tome_2_Ondes_EM_Vide_et_Milieux/Chapitres/Chapitre_5_Rayonnement_dipolaire_diffusion.pdf','l2',1,'2026-08-13 20:53:56'),(16,16,'Chapitre 1 - Introduction aux milieux diélectriques','cours-tome-3-ondes-em-dielectriques-ch1-introduction-dielectriques','Polarisation de la matière, vecteur déplacement électrique D, polarisabilité moléculaire et condensateurs.',NULL,'/assets/downloads/garing_decoupe/Tome_3_Ondes_EM_Dielectriques/Chapitres/Chapitre_1_Introduction_Dielectriques.pdf','l3',1,'2026-08-13 20:53:56'),(17,17,'Chapitre 1 - Indice d\'un milieu et dispersion','cours-tome-3-ondes-em-dielectriques-ch2-indice-d-un-milieu','Modèle de l\'électron lié, formule de Sellmeier, absorption et vitesses de groupe/phase.',NULL,'/assets/downloads/garing_decoupe/Tome_3_Ondes_EM_Dielectriques/Chapitres/Chapitre_2_Indice_d_un_milieu.pdf','l3',1,'2026-08-13 20:53:56'),(18,18,'Chapitre 1 - Ondes électromagnétiques dans les diélectriques isotropes','cours-tome-3-ondes-em-dielectriques-ch3-ondes-dielectriques-isotropes','Lois de Snell-Descartes, coefficients de Fresnel, réflexion totale, ondes évanescentes et fibres optiques.',NULL,'/assets/downloads/garing_decoupe/Tome_3_Ondes_EM_Dielectriques/Chapitres/Chapitre_3_Ondes_Dielectriques_Isotropes.pdf','l3',1,'2026-08-13 20:53:56'),(19,19,'Chapitre 1 - Optique des milieux diélectriques anisotropes','cours-tome-3-ondes-em-dielectriques-ch4-dielectriques-anisotropes','Tenseur de permittivité, ellipsoïde des indices, biréfringence, lames retardatrices et activité optique.',NULL,'/assets/downloads/garing_decoupe/Tome_3_Ondes_EM_Dielectriques/Chapitres/Chapitre_4_Dielectriques_Anisotropes.pdf','l3',1,'2026-08-13 20:53:56'),(20,20,'Chapitre 1 - Diélectriques non linéaires et optique non linéaire','cours-tome-3-ondes-em-dielectriques-ch5-dielectriques-non-lineaires','Susceptibilité non linéaire, génération de seconde harmonique, effet Kerr et auto-focalisation.',NULL,'/assets/downloads/garing_decoupe/Tome_3_Ondes_EM_Dielectriques/Chapitres/Chapitre_5_Dielectriques_Non_Lineaires.pdf','l3',1,'2026-08-13 20:53:56'),(21,21,'Chapitre 1 - Cinematique du point','cours-hprepa-meca-1-ch1-cinematique-du-point','Cours complet, méthodes et exercices corrigés pas à pas (H-Prepa : Mécanique 1re année (MPSI/PCSI)).',NULL,'/assets/downloads/H-prepa_decoupe/H_Prepa_Mecanique_1re_annee_MPSI_PCSI_PTSI/Chapitre_01_Cinematique_du_point.pdf','l1',1,'2026-08-13 21:22:14'),(22,22,'Chapitre 1 - Principe Fondamental Dynamique','cours-hprepa-meca-1-ch2-principe-fondamental-dynamique','Cours complet, méthodes et exercices corrigés pas à pas (H-Prepa : Mécanique 1re année (MPSI/PCSI)).',NULL,'/assets/downloads/H-prepa_decoupe/H_Prepa_Mecanique_1re_annee_MPSI_PCSI_PTSI/Chapitre_02_Principe_Fondamental_Dynamique.pdf','l1',1,'2026-08-13 21:22:14'),(23,23,'Chapitre 1 - Energie mecanique','cours-hprepa-meca-1-ch3-energie-mecanique','Cours complet, méthodes et exercices corrigés pas à pas (H-Prepa : Mécanique 1re année (MPSI/PCSI)).',NULL,'/assets/downloads/H-prepa_decoupe/H_Prepa_Mecanique_1re_annee_MPSI_PCSI_PTSI/Chapitre_03_Energie_mecanique.pdf','l1',1,'2026-08-13 21:22:14'),(24,24,'Chapitre 1 - Oscillateurs harmoniques','cours-hprepa-meca-1-ch4-oscillateurs-harmoniques','Cours complet, méthodes et exercices corrigés pas à pas (H-Prepa : Mécanique 1re année (MPSI/PCSI)).',NULL,'/assets/downloads/H-prepa_decoupe/H_Prepa_Mecanique_1re_annee_MPSI_PCSI_PTSI/Chapitre_04_Oscillateurs_harmoniques.pdf','l1',1,'2026-08-13 21:22:14'),(25,25,'Chapitre 1 - Moment cinetique et Forces centrales','cours-hpre